			(function() {
				function fixA11y(el) {
					// Remove empty paragraphs (created when browser auto-closes <p> before block elements)
					var paras = [];
					if (el.matches && el.matches('p')) paras.push(el);
					if (el.querySelectorAll) paras = paras.concat(Array.prototype.slice.call(el.querySelectorAll('p')));
					paras.forEach(function(p) {
						if (p.querySelector('img, iframe, video, audio, canvas, svg, input, select, textarea, button, object, embed')) return;
						var inner = p.innerHTML.replace(/&nbsp;/gi, '').replace(/<br\s*\/?>/gi, '').trim();
						if (inner === '' && p.parentNode) {
							p.parentNode.removeChild(p);
						}
					});

					// Fix images missing alt attribute
					var imgs = [];
					if (el.matches && el.matches('img:not([alt])')) imgs.push(el);
					if (el.querySelectorAll) imgs = imgs.concat(Array.prototype.slice.call(el.querySelectorAll('img:not([alt])')));
					imgs.forEach(function(img) {
						var src = img.getAttribute('src') || '';
						var name = src.split('/').pop().split('?')[0].replace(/[-_]/g, ' ').replace(/\.\w+$/, '').trim();
						img.setAttribute('alt', name || 'image');
					});

					// Fix iframes missing title attribute
					var iframes = [];
					if (el.matches && el.matches('iframe:not([title])')) iframes.push(el);
					if (el.querySelectorAll) iframes = iframes.concat(Array.prototype.slice.call(el.querySelectorAll('iframe:not([title])')));
					iframes.forEach(function(iframe) {
						var src = iframe.getAttribute('src') || '';
						var title = 'Embedded content';
						try {
							var host = new URL(src).hostname.replace(/^www\./, '');
							if (host) title = host.split('.')[0].charAt(0).toUpperCase() + host.split('.')[0].slice(1) + ' embed';
						} catch(e) {}
						iframe.setAttribute('title', title);
					});

					// Fix table headers: add scope="col" to <th> in <thead>
					var tables = [];
					if (el.matches && el.matches('table')) tables.push(el);
					if (el.querySelectorAll) tables = tables.concat(Array.prototype.slice.call(el.querySelectorAll('table')));
					tables.forEach(function(table) {
						var thead = table.querySelector('thead');
						if (!thead) return;
						var ths = thead.querySelectorAll('th:not([scope])');
						ths.forEach(function(th) { th.setAttribute('scope', 'col'); });
					});

					// Fix empty links (no text, no aria-label, no title)
					var links = [];
					if (el.matches && el.matches('a')) links.push(el);
					if (el.querySelectorAll) links = links.concat(Array.prototype.slice.call(el.querySelectorAll('a')));
					links.forEach(function(link) {
						if (link.getAttribute('aria-label') || link.getAttribute('title')) return;
						if (link.textContent.trim() !== '') return;
						var img = link.querySelector('img');
						if (img && (img.getAttribute('alt') || '').trim()) {
