					if (el.querySelectorAll) nwwLinks = nwwLinks.concat(Array.prototype.slice.call(el.querySelectorAll('a[aria-label="opens a new window"]')));
					nwwLinks.forEach(function(link) {
						var label = 'Link (opens in a new window)';
						try {
							var host = new URL(link.href).hostname.replace(/^www\./, '');
							if (host) {
								var name = host.split('.')[0];
								label = name.charAt(0).toUpperCase() + name.slice(1) + ' (opens in a new window)';
