					var label = 'Read more';
					try {
						var path = new URL(link.href).pathname.replace(/^\/|\/$/g, '');
						var slug = path.split('/').pop();
						if (slug) {
							label = 'Read more about ' + slug.replace(/[-_]/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); });
