			// WCAG 2.2.2: Add pause/play button to auto-playing BB sliders
			(function() {
				function addSliderPauseButtons() {
					var wrappers = document.querySelectorAll('.bx-wrapper');
					wrappers.forEach(function(wrapper) {
						if (wrapper.querySelector('.a11y-slider-pause')) return;
						var viewport = wrapper.querySelector('.bx-viewport');
						if (!viewport) return;

						// Only target sliders with more than one actual slide
						var slides = viewport.querySelectorAll('.fl-slide, .fl-post-carousel-post, .fl-post-grid-post');
						var realSlides = Array.prototype.slice.call(slides).filter(function(s) {
							return !s.classList.contains('bx-clone');
						});
						if (realSlides.length <= 1) return;

						var slider = wrapper.closest('.fl-module-content-slider, .fl-module-post-slider, .fl-module-post-carousel');
						if (!slider) return;

						var slidesEl = viewport.querySelector('.bx-slider, ul, .fl-slides');
						if (!slidesEl) return;

						var btn = document.createElement('button');
						btn.className = 'a11y-slider-pause';
						btn.setAttribute('aria-label', 'Pause slideshow');
						btn.innerHTML = '<i class="fas fa-pause" aria-hidden="true"></i>';
						btn.type = 'button';

						var paused = false;
						var observer = null;

						// Detect auto-play by watching for style changes on the slides element
						var checkCount = 0;
						var detectObserver = new MutationObserver(function() {
							checkCount++;
							if (checkCount >= 2) {
								detectObserver.disconnect();
								wrapper.style.position = 'relative';
								wrapper.appendChild(btn);
							}
						});
						detectObserver.observe(slidesEl, { attributes: true, attributeFilter: ['style'] });
						setTimeout(function() { detectObserver.disconnect(); }, 15000);

						btn.addEventListener('click', function() {
							paused = !paused;
							if (paused) {
								btn.setAttribute('aria-label', 'Play slideshow');
								btn.innerHTML = '<i class="fas fa-play" aria-hidden="true"></i>';
								var currentStyle = slidesEl.getAttribute('style');
								observer = new MutationObserver(function(mutations) {
									mutations.forEach(function(m) {
										if (m.attributeName === 'style') {
											slidesEl.setAttribute('style', currentStyle);
										}
									});
								});
								observer.observe(slidesEl, { attributes: true, attributeFilter: ['style'] });
							} else {
								btn.setAttribute('aria-label', 'Pause slideshow');
								btn.innerHTML = '<i class="fas fa-pause" aria-hidden="true"></i>';
								if (observer) { observer.disconnect(); observer = null; }
							}
						});
					});
				}

				// Run after BB initializes sliders
				if (document.readyState === 'complete') {
					setTimeout(addSliderPauseButtons, 1000);
				} else {
					window.addEventListener('load', function() {
						setTimeout(addSliderPauseButtons, 1000);
					});
				}
			})();

